import{_ as n,l as i,o as e,c as l,v as t,p as s,x as o,d as E,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"稳健、聚类与多重检验","description":"","frontmatter":{"title":"稳健、聚类与多重检验","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/inference-robust-cluster.md","filePath":"econ/inference-robust-cluster.md","lastUpdated":1789023840000}'),p={name:"econ/inference-robust-cluster.md"};function h(B,a,u,m,f,A){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="稳健、聚类与多重检验" tabindex="-1">稳健、聚类与多重检验 <a class="header-anchor" href="#稳健、聚类与多重检验" aria-label="Permalink to &quot;稳健、聚类与多重检验&quot;">​</a></h1><div class="epigraph"><p>点估计对准了参数，名义标准误还可以全错：异方差、组内相关、以及一桌子系数里最显著的那个，都会把 $p$ 值变成装饰。</p><footer>—— White, A Heteroskedasticity-Consistent Covariance Matrix Estimator, Econometrica 1980；Bertrand, Duflo and Mullainathan, QJE 2004；Romano and Wolf 逐步多重检验</footer></div><p><a href="/econ/multiple-testing-econ">上一课</a>把家族错误率钉在多假设上。本课缺口是把稳健协方差、聚类、以及多个假设收成一套报告纪律。机器学习与因果下一课换估计装置；本课先保证「显著」两个字有内容。识别与回归课序在此收束精度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Gauss–Markov 的球形误差在截面异方差、时间序列相关、州–年面板里几乎从不真。White：异方差下 OLS 仍一致，协方差用残差平方加权的「三明治」。聚类：同一州的年份之间 \\(u_{it}\\) 相关，有效样本接近州的个数而不是州–年格点数。Bertrand–Duflo–Mullainathan 演示 DiD 忽略这一点会严重过度拒绝。缺口是：聚类层级要对准赋值发生的层级；乱聚到过细，名义 \\(p\\) 又会过小。</p><p>多重检验：二十个结果、五个子样本，期望有一个「\\(p\\lt 0.05\\)」。Bonferroni 过保守；Benjamini–Hochberg FDR、Romano–Wolf 逐步法在功效与控制之间折中。预注册与单一主结果是设计手段，不是统计公式。</p><p><span class="marginnote">Cameron–Gelbach–Miller：聚类数少时用野 bootstrap。Abadie–Athey–Imbens–Wooldridge：聚类应对准设计（哪些单位被随机或被政策），不是「所有看起来相关的」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>默认报告异方差稳健；面板、州政策报告聚类稳健。双向聚类（公司与时间）在金融量化栏更常见，本课只标：第二维要有足够簇。HAC（Newey–West）是时间维的三明治，滞后截断要声明。不要「换聚类直到显著」。</p>',9)),(e(),s(c,null,{default:o(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20POINT%5B%22%E7%82%B9%E4%BC%B0%E8%AE%A1%22%5D%20--%3E%20SE%5B%22%E5%8D%8F%E6%96%B9%E5%B7%AE%22%5D%0A%20%20HET%5B%22%E5%BC%82%E6%96%B9%E5%B7%AE%22%5D%20--%3E%20WHITE%5B%22White%20%E4%B8%89%E6%98%8E%E6%B2%BB%22%5D%0A%20%20CLU%5B%22%E7%BB%84%E5%86%85%E7%9B%B8%E5%85%B3%22%5D%20--%3E%20CL%5B%22%E8%81%9A%E7%B1%BB%E5%88%B0%E8%B5%8B%E5%80%BC%E5%B1%82%22%5D%0A%20%20MANY%5B%22%E5%A4%9A%E4%B8%AA%E5%81%87%E8%AE%BE%22%5D%20--%3E%20FWER%5B%22FWER%20%2F%20FDR%22%5D%0A%20%20SE%20--%3E%20INF%5B%22%E8%A6%86%E7%9B%96%E4%B8%8E%E5%8A%9F%E6%95%88%22%5D%0A%20%20WHITE%20--%3E%20INF%0A%20%20CL%20--%3E%20INF%0A%20%20FWER%20--%3E%20INF%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>量化栏的<a href="/quant/clustered-se">聚类标准误</a>写金融应用；本课写同一套推断逻辑，不重写那些表，也不进限价簿。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是把估计量的抽样变异写对。三明治的面包是梯度、肉是残差的二阶矩；聚类把肉在簇内加总，等于允许簇内任意相关、簇间独立。簇间仍相关（空间、共同市场）则仍低估。多重检验把「至少一个假阳性」当成家族错误率，惩罚搜刮。</p><p>与识别：推断再对，排除失败的 IV 仍然错。本课不管偏误，管方差。弱工具的名义 \\(t\\) 失败是上一课的覆盖问题，不是聚类能修的。</p><p><span class="marginnote">Moulton：回归元在组层、误差在组层，即便「看起来 \\(N\\) 很大」，信息量是组数。教育政策用学校，劳动用州，都先数簇。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有论文改成 Romano–Wolf。不处理空间 HAC 的完整菜单。机器学习课会对交叉拟合的标准误另写；本课的三明治不自动覆盖数据驱动的带宽、惩罚参数。课序下一课 ML 因果仍要本课的聚类意识：样本划分不能当独立若簇还在。</p><p>后课默认：报告与赋值层级匹配的聚类；多结果要有家族控制或预先主结果。White 不是聚类的替代。精度正确不能补识别失败。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>White：异方差下一致协方差；不管组内相关。</li><li>聚类到政策 / 随机化发生的层；簇少则野 bootstrap。</li><li>多重检验：FWER 或 FDR；搜刮子样本会制造显著。</li><li>量化栏金融聚类是应用，定义相同。</li><li>出处：White, <em>Econometrica</em> 1980；Bertrand, Duflo and Mullainathan, <em>QJE</em> 2004；Cameron, Gelbach and Miller；Romano and Wolf。</li></ul>',10))])}const D=n(p,[["render",h]]);export{b as __pageData,D as default};
